@startuml

class Customer {
  + name : string
  + surname : string
  + email : string
  + telephone : string
  + address : string
}

class Dish {
  + name : string
  + preparation_time : time
}

class Order {
  + total_cost : double
  + estimated_delivery_time : time
  + status : string
}

enum OrderStatus {
  placed
  in preparation
  in delivery
  delivered
}

Customer "1" -- "*" Order : places

Order "1" *-- "1..*" Dish : contains

@enduml

